import {SALARY_PRESETS,MILESTONES,journeyStatus,productDemand} from './progression.js';
import {chineseNameSuggestions,loadUsers,createUser,activateUser,renameUser,userSaveKey,userModeKey} from './users.js';
import {CONTACTS,STARTER_COUNTS} from './contacts.js';
import {clientTasks,completeClientDemo,markClientDemoSent,dayUsed,today,agenda,addAppointment,fulfillAppointment,nextDay,projectLibrary,projectMessage,completeDemo,confirmProduct,performAction,makeLead,CONTACT_POOLS,applyConversation,SKILLS,effects,setTraining,BACKGROUNDS,migrateSave,ACTIONS,TOOLS,initial,used,setPlan,accept,buy,advance,resolveEvent,validSave} from './engine.js';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',case:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12h18M10 12v3h4v-3"/>',box:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7 5.8l9 5"/>',chart:'<path d="M4 3v17h17M8 15v-4M13 15V7M18 15V4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 4M12 17h.01"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 11h18M8 15h2M14 15h2"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 8h18M21 12h-6v5h6M17 14.5h.1"/>',energy:'<path d="m13 2-9 12h7l-1 8 10-13h-8z"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',megaphone:'<path d="m3 9 17-5v15L3 14zM6 15l2 6h4l-2-5M20 9h2v5h-2"/>',coffee:'<path d="M4 8h13v9a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4zM17 9h2a3 3 0 0 1 0 6h-2M7 2v3M12 2v3"/>',play:'<path d="m9 5 10 7-10 7z"/>',flag:'<path d="M5 22V3m0 0c5-4 9 4 15 0v11c-6 4-10-4-15 0"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',home:'<path d="m3 10 9-7 9 7v11H3zM9 21v-8h6v8"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const icon=id=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[id]||icons.grid}</svg>`;const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>'¥'+Math.round(n).toLocaleString('zh-CN');let userRegistry,userStorageError='';try{userRegistry=loadUsers(localStorage)}catch(error){userStorageError=error.message;userRegistry={active:'unavailable',users:[{id:'unavailable',name:'临时用户'}]};}let activeUser=userRegistry.users.find(u=>u.id===userRegistry.active);const KEY=userSaveKey(activeUser.id),MODE_KEY=userModeKey(activeUser.id);let gameMode='simulation';try{gameMode=localStorage.getItem(MODE_KEY)==='simple'?'simple':'simulation'}catch{}let walletFilter='all';let chatBusy=false,chatLeadId=null;let s=initial(),view='overview',storageOK=true,hasSave=false,toastTimer;
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(validSave(data)){s=migrateSave(data);hasSave=true;}else storageOK=false}}catch{storageOK=false}
const modal=document.querySelector('#modal');function save(){if(!hasSave)return;if(userStorageError){storageOK=false;document.querySelector('#save-status').textContent='用户存储不可用';return;}try{localStorage.setItem(KEY,JSON.stringify(s));storageOK=true}catch{storageOK=false}document.querySelector('#save-status').textContent=storageOK?'本机自动存档':'存档不可用，请勿关闭'}
function toast(text){const t=document.querySelector('#toast');(modal.open?modal:document.body).append(t);t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200)}
function show(content){modal.classList.remove('setup-modal','chat-modal','messenger-modal','scrm-modal','wechat-directory-modal');document.querySelector('#modal-content').innerHTML='<div class="modal-inner">'+content+'</div>';if(!modal.open)modal.showModal();queueMicrotask(installSimpleChoices)}
function close(){if(chatBusy){toast('AI 正在处理中，请稍候');return}if(!hasSave)return;modal.close();modal.classList.remove("setup-modal")}
const top=(label,title)=>`<div class="modal-top"><span class="eyebrow">${label}</span><button class="close" data-do="close" aria-label="关闭弹窗">×</button></div><h2>${title}</h2>`;
function render(){const userButton=document.querySelector('#user-manager');if(userButton){userButton.title='当前创业者：'+activeUser.name;userButton.querySelector('small').textContent=activeUser.name;}const existingStats=document.querySelector('#stats');if(existingStats)document.querySelector('main header').after(existingStats);document.body.dataset.view=view;updateModeLabel();document.querySelector('#new-game').innerHTML=s.gender?portrait(s.gender,'small'):'独';document.querySelector('#new-game').title='创始人设定 / 开启新故事';document.querySelector('#company-name').textContent=s.name;document.querySelector('#week-label').textContent='第 '+String(Math.min(s.week,52)).padStart(2,'0')+' 周 · 第 '+(s.day||1)+' 天';document.querySelector('#stats').innerHTML=[['账户余额',fmt(s.cash),'wallet',`预计可支撑 <span class="positive">${Math.max(0,Math.floor(s.cash/(850+(s.tools.includes('automation')?120:0))))} 周</span> 固定开销`,''],['今日可做事项',(2-dayUsed(s))+'<small>/ 2 件</small>','clock','打开工具不占次数，执行工作占 1 件',''],['个人精力',s.energy+'<small>/ 100</small>','energy',s.energy>=45?'状态良好 · 可以全力投入':s.energy>=25?'有些疲惫 · 交付效率 75%':'需要休息 · 交付效率 50%',s.energy>=45?'positive':'amber'],['市场信誉',s.reputation+'<small>/ 100</small>','star',`已完成 ${s.completed} 个项目 · 触达 ${s.reach} 人`,'']].map(([label,value,ic,foot,color])=>`${ic==='wallet'?'<button type="button" class="stat wallet-entry" data-view="finance" aria-label="账户余额，打开财务情况">':'<article class="stat">'}<div class="stat-head" title="${esc(foot.replace(/<[^>]*>/g,''))}"><span>${label}</span>${icon(ic)}</div><div class="stat-value ${color}">${value}</div><div class="stat-foot">${foot}${ic==='wallet'?'<span class="wallet-entry-link">打开财务情况 ›</span>':''}</div>${ic==='wallet'?'</button>':'</article>'}`).join('');document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);if(b.classList.contains('nav'))b.setAttribute('aria-current',b.dataset.view===view?'page':'false')});document.querySelector('#view-root').innerHTML=view==='overview'?overview():view==='orders'?orders():view==='product'?products():finance();document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));integrateDeskHUD();installScheduleDrag();const earned=Object.keys(s.journey.unlocked).map(Number).filter(n=>n>(s.journey.announced||0));if(earned.length){s.journey.announced=Math.max(...earned);const message='里程碑达成：'+earned.map(n=>MILESTONES[n-1].title).join(' · ');queueMicrotask(()=>toast(message));}save()}

function actionHint(id){const e=effects(s),fatigue=s.energy<25?.5:s.energy<45?.75:1;return {delivery:`每时段 ${Math.floor(e.delivery*fatigue)} 标准工时 · 能力 ${s.skills.delivery}`,prospect:`每时段最多 ${e.prospect} 人 · 剩余潜客池 ${s.contactPool} 人`,develop:!s.productPlan?'设定产品方案，让 AI 评估变现潜力':s.product===100?'已上线，可查看方案与评估':`每时段研发 +${e.develop}% · 交付与洞察共同影响`,market:`触达 +${e.market} / 时段，同时带来咨询`,research:`每时段匹配度 +${e.research} · 当前 ${s.productFit}%`,train:`${SKILLS[s.trainingTarget].name} +4 / 时段`,rest:'恢复 18 点精力'}[id]}
function skillPanel(){return `<section class="skills-panel" aria-label="创始人四项能力"><div class="section-heading"><h2>一个人，四种能力。</h2><span class="meta">工作中成长 · 专项学习补短板 · 上限 100</span></div><div class="skill-grid">${Object.entries(SKILLS).map(([id,k])=>`<article class="skill-card" title="${esc(k.desc)}"><div class="flex"><strong>${k.name}</strong><b>${s.skills[id]}<small> / 100</small></b></div><div class="progress-track"><i style="width:${s.skills[id]}%"></i></div><p>${k.desc}</p></article>`).join('')}</div></section>`}

function leadCard(l){return `<article class="lead-card"><div class="client-line"><span class="client-avatar">${esc(l.client[0])}</span>${esc(l.client)}<span style="margin-left:auto">${l.weeks} 周工期</span></div><h3>${esc(l.title)}</h3><div class="lead-details"><span>${l.hours} 小时工作量</span><span>${esc(l.source||'主动拓客')} · ${l.status==='converted'?'愿意合作':l.status==='rejected'?'暂不合作':'尚未转化'}</span></div><div class="lead-bottom"><strong class="price">${fmt(l.price)}</strong><button class="outline" data-accept="${l.id}" ${s.ended||s.pendingEvent?'disabled':''}>${l.status==='converted'?'查看合作':l.status==='rejected'?'查看反馈':'与客户沟通'}</button></div></article>`}
function overview(){return `${founderSummary()}${skillPanel()}<div class="main-grid immersive-workspace"><section class="planner"><div class="section-heading"><h2>我的工作位</h2><span class="meta">WEEK ${String(Math.min(s.week,52)).padStart(2,'0')}</span></div><p class="planner-desc">坐下来。你的客户、产品和想法，都在这块屏幕里。</p>${desktopApps()}</section></div><div class="workspace-journal"><section><div class="section-heading"><h2>创业手记</h2><span class="meta">每一步，都算数</span></div><div class="journal">${s.logs.slice(0,3).map(l=>`<div class="journal-item"><p>${esc(l.text)}</p><small>第 ${l.week} 周</small></div>`).join('')}</div></section></div>`}
function orders(){return `<h2 class="page-title">客户与订单</h2><button class="outline" data-library>我的项目库</button><p class="page-intro">承诺之前，先看看你的日程。最多同时进行 3 个项目，交付优先处理最早到期的订单。</p>${clientTaskCards()}<div class="section-heading"><h2>进行中的项目 <span class="count">${s.projects.length} / 3</span></h2><button class="outline" data-view="overview">安排交付</button></div><div class="project-list">${s.projects.map(p=>`<article class="panel"><div class="project-row"><div><h3>${esc(p.title)}</h3><span class="meta">${esc(p.client)} · 第 ${p.due} 周到期 ${p.late?'<span class="negative"> · 已逾期</span>':''}</span></div><div style="text-align:right"><strong class="price">${fmt(p.price*.7)}</strong><div class="meta">交付后可收尾款</div></div></div><div class="progress-track"><i style="width:${p.progress/p.hours*100}%"></i></div><div class="flex meta"><span>已完成 ${p.progress} / ${p.hours} 小时</span><span>${Math.round(p.progress/p.hours*100)}%</span></div></article>`).join('')||'<div class="empty">还没有在做的项目。先通过寻找客户或内容营销获取线索，再与客户沟通转化。</div>'}</div><div class="section-heading"><h2>待沟通客户</h2><span class="meta">主动潜客池 ${s.contactPool} 人 · 内容营销也可带来咨询</span></div><div class="wide-grid">${s.leads.map(leadCard).join('')||'<div class="empty">目前没有新机会，先去寻找客户。</div>'}</div>`}
function products(){return `<h2 class="page-title">让专业能力，重复创造价值。</h2><button class="outline" data-library>我的项目库</button><p class="page-intro">短期少接一点单，长期少卖一点时间。产品每天自动成交，销量由触达、信誉、需求匹配度、转化价值和定价共同决定。调研找到真正的问题，研发把解决方案做出来。</p><article class="panel"><div class="product-hero"><div><span class="pill">${s.product===100?(s.productEvaluation&&!s.productEvaluation.canMonetize?'已上线 · 暂不变现':'已上线 · 自动销售'):s.productPlan?'研发中 · 数字产品':'等待产品立项'}</span><h3 style="margin-top:15px;font-size:23px">${esc(s.productPlan?.direction||'尚未定义产品方案')}</h3><p>${esc(s.productPlan?.solution||'设定方向、用户、场景、解决方式和售价，让 DeepSeek 评估变现潜力。')}</p></div><div class="product-symbol">${icon('box')}</div></div>${productSummary()}<div class="fit-box"><strong>运营需求匹配度 ${s.productFit}%</strong><p>当前预计每日 ${productDemand(s).toFixed(2)} 单（不足 1 单的需求累积到后续日期） · 安排需求调研，每 8 小时 +${effects(s).research} 点（最高 100）。</p></div><div class="flex"><span>研发进度</span><strong class="positive">${s.product}%</strong></div><div class="progress-track"><i style="width:${s.product}%"></i></div><div class="flex"><span class="meta">售价 ${fmt(s.productPlan?.price||99)} / 份 · 已售 ${s.sales} 份 · 上线次日开始自动销售</span><button class="outline" data-branch="develop">${s.productPlan?'查看研发方案':'设定产品方案'}</button></div></article><div class="section-heading spaced"><h2>给自己添一点助力</h2><span class="meta">工具是成本，也可以是投资</span></div><div class="wide-grid">${TOOLS.map(t=>`<article class="panel tool-card"><div class="action-icon green">${icon(t.id==='templates'?'box':'energy')}</div><h3 style="margin-top:17px">${t.name}</h3><p>${t.desc}</p><div class="tool-price">${fmt(t.cost)} <small>${t.weekly?'+ ¥'+t.weekly+' / 周':'一次性投入'}</small></div><button class="${s.tools.includes(t.id)?'secondary':'outline'}" data-buy="${t.id}" ${s.tools.includes(t.id)||s.cash<t.cost||s.ended?'disabled':''}>${s.tools.includes(t.id)?'已启用':'购入工具'}</button></article>`).join('')}</div>`}
function finance(){const pending=s.projects.reduce((n,p)=>n+Math.round(p.price*.7),0),rows=s.ledger.map((l,i)=>({...l,index:i})).filter(l=>walletFilter==='all'||(walletFilter==='income'?l.amount>0:l.amount<0));return `<section class="pay-app"><header class="pay-header"><div><span class="pay-logo">财</span><strong>财务情况 <small>模拟账户</small></strong></div><span>我的 · ${esc(s.name)}</span></header><div class="pay-balance"><div class="pay-label">账户余额（元）</div><div class="pay-amount">${moneyText(s.cash)}</div><div class="pay-balance-foot"><span>游戏经营账户</span><span>余额随收付款实时更新</span></div></div><div class="pay-summary"><div><span>累计收入</span><strong class="pay-income">+${moneyText(s.totalIncome)}</strong></div><div><span>累计支出</span><strong>${moneyText(s.totalExpense)}</strong></div><div><span>待收尾款</span><strong>${moneyText(pending)}</strong></div></div><div class="pay-notice">启动资金 ¥${moneyText(s.initialCash)} · 预付款签约到账，尾款交付到账<br>当前余额已扣除开发费用、经营开销及发生的赔付。</div><section class="pay-bills"><div class="pay-bill-heading"><h2>账单</h2><span>最近 ${s.ledger.length} 笔记录</span></div><div class="pay-filters">${[['all','全部'],['income','收入'],['expense','支出']].map(([id,label])=>`<button data-wallet-filter="${id}" class="${walletFilter===id?'selected':''}" aria-pressed="${walletFilter===id}">${label}</button>`).join('')}</div>${rows.map(l=>`<button class="pay-bill-row" data-wallet-bill="${l.index}"><span class="pay-bill-icon ${l.amount>0?'incoming':''}">${l.amount>0?'收':'付'}</span><span class="pay-bill-text"><strong>${esc(l.note)}</strong><small>第 ${l.week} 周${l.day?' · 第 '+l.day+' 天':''} · 交易成功</small></span><b class="${l.amount>0?'pay-income':''}">${l.amount>0?'+':'−'}${moneyText(Math.abs(l.amount))}</b><span class="pay-chevron">›</span></button>`).join('')||'<div class="pay-empty">暂无这类账单<br><small>你的第一笔收付款会出现在这里</small></div>'}</section><footer class="pay-footer">一人公司模拟器 · 游戏内账单</footer></section>`}
function moneyText(n){return Number(n).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}
function openBill(index){const l=s.ledger[index];if(!l)return;show(top('PAYMENT DETAILS','账单详情')+`<div class="pay-detail"><span class="pay-bill-icon ${l.amount>0?'incoming':''}">${l.amount>0?'收':'付'}</span><h3>${esc(l.note)}</h3><strong>${l.amount>0?'+':'−'}${moneyText(Math.abs(l.amount))}</strong><p>交易成功</p></div><div class="report-line"><span>交易时间</span><span>第 ${l.week} 周${l.day?' · 第 '+l.day+' 天':''}</span></div><div class="report-line"><span>收支类型</span><span>${l.amount>0?'收入':'支出'}</span></div><div class="report-line"><span>账户</span><span>${esc(s.name)} · 模拟余额</span></div><p class="meta">记录来自本局游戏中的实际收付款。</p>`)}

function report(r){show(top('WEEK '+String(r.week).padStart(2,'0')+' · REVIEW','又向前走了一周。')+`<div class="report-line"><span>本周到账</span><span class="positive">+ ${fmt(r.income)}</span></div><div class="report-line"><span>本周支出</span><span>${fmt(r.expense)}</span></div><div class="report-line"><span>现金变化</span><span class="${r.net>=0?'positive':'negative'}">${r.net>=0?'+ ':''}${fmt(r.net)}</span></div><div class="report-notes">${(r.notes.length?r.notes:['这周没有新增业务进展，休息也是经营的一部分。']).map(n=>`<div>${esc(n)}</div>`).join('')}</div><div class="modal-actions"><button class="primary" data-do="after-report">${s.ended?'查看经营结局':s.pendingEvent?'有件事需要决定':s.leads.some(l=>['new','followup'].includes(l.status))?'去与客户沟通':'迎接第 '+s.week+' 周'}</button></div>`)}
function event(){const opportunity=s.pendingEvent==='opportunity';show(top('FOUNDER’S CHOICE',''+(opportunity?'走出工作室，认识一些人？':'同行发来了一条求助消息。'))+`<p>${opportunity?'一个小型行业聚会向你发出邀请。参加需要花钱，但也可能让更多人知道你在做什么。':'一位同行遇到了紧急技术问题，希望你能帮忙。没有报酬，但他会记住这次帮助。'}</p><button class="choice" data-event="a" ${opportunity&&s.cash<600?'disabled':''}>${opportunity?'去认识一些潜在合作伙伴':'花点精力帮他解决问题'}<small>${opportunity?'现金 -¥600 · 触达 +15 · 信誉 +3':'精力 -12 · 信誉 +6'}</small></button><button class="choice" data-event="b">${opportunity?'留在工作室，整理自己的节奏':'坦诚说明现在需要休息'}<small>${opportunity?'精力 +8，无现金支出':'精力 +5，不影响信誉'}</small></button>`)}
function ending(){const bankrupt=s.ended==='bankrupt';const title=bankrupt?'暂时停下来，不代表白走了。':s.ended==='victory'?'你赢了：收入不再只来自你的时间。':'第一年结束，创业挑战尚未通关。';show(top('YEAR ONE · YOUR STORY',title)+`<p>${bankrupt?'现金已经不足以支付支出。本次经营结束。下一次，试着先接小项目、尽早交付，给现金留出余地。':s.ended==='victory'?'五个里程碑全部达成。同一款产品连续 28 天自动成交，到账达到原月薪的两倍。':'撑过一年不等于胜利。看看还差哪一步，把经验带进下一段故事。'}</p><div class="report-line"><span>已结算周数</span><span>${Math.min(52,s.week-1)} 周</span></div><div class="report-line"><span>创业里程碑 / 原月薪</span><span>${journeyStatus(s).done} / 5 · ${fmt(s.journey.salary)}</span></div><div class="report-line"><span>近 28 天自动收入 / 胜利目标</span><span>${fmt(journeyStatus(s).recurring)} / ${fmt(s.journey.salary*2)}</span></div><div class="report-line"><span>连续自动成交</span><span>${journeyStatus(s).streak} 天 / 至少 28 天</span></div><div class="report-line"><span>期末现金</span><span>${fmt(s.cash)}</span></div><div class="report-line"><span>完成项目 / 产品销量</span><span>${s.completed} / ${s.sales}</span></div><div class="report-line"><span>市场信誉 / 剩余精力</span><span>${s.reputation} / ${s.energy}</span></div><div class="modal-actions"><button class="secondary" data-journey>查看里程碑</button><button class="secondary" data-do="close">查看公司</button><button class="primary" data-do="new">开始新的故事</button></div>`)}
function portrait(gender,extra=''){return `<span class="portrait ${gender==='female'?'female':'male'} ${extra}" role="img" aria-label="${gender==='female'?'女性':'男性'}创始人像素头像"></span>`}
function founderSummary(){const b=BACKGROUNDS[s.background];return `<div class="founder-summary">${s.gender?portrait(s.gender,'small'):'<span class="avatar">独</span>'}<div><strong>${b.name}</strong><span> · ${s.gender?(s.gender==='female'?'女性创始人':'男性创始人'):'创始人'} · 启动资金 ${fmt(s.initialCash)}</span></div><button class="text-btn" data-do="story">我的起点</button></div>`}
let setupStep=1;
const ROLE_ART={development:'career-development.png',product:'career-product.png',operations:'career-operations.png',sales:'career-sales.png'};
function newGame(){if(activeUser.needsName){openRegistration();return;}setupStep=1;show(`<div class="modal-top"><span class="eyebrow">SOLO INC. / CREATE YOUR FOUNDER</span><button type="button" class="text-btn" data-open-users>用户：${esc(activeUser.name)} · 切换</button>${hasSave?'<button class="close" data-do="close" aria-label="关闭弹窗">×</button>':''}</div><div class="selection-heading"><div><h2 id="setup-title" tabindex="-1">选择你的职业起点</h2><p id="setup-subtitle">你擅长的事，是这家公司的第一笔资产。</p></div><div class="wizard-steps" aria-label="创建角色步骤"><span id="step-one" class="current" aria-current="step">01 选择岗位</span><i></i><span id="step-two">02 塑造角色</span></div></div><form id="setup"><section id="career-step"><fieldset class="role-select-grid"><legend class="sr-only">选择职业背景</legend>${Object.entries(BACKGROUNDS).map(([id,b],i)=>`<label class="role-select-card role-${id}"><input type="radio" name="background" value="${id}" ${id==='development'?'checked':''} required><div class="role-art"><img src="${ROLE_ART[id]}" alt="${b.name}职业立绘" loading="eager"><span class="role-number">0${i+1}</span><span class="selected-mark">已选择</span><div class="role-art-title"><span>${['DEVELOPER','PRODUCT','OPERATIONS','SALES'][i]}</span><h3>${b.name}</h3><p>${b.tag}</p></div></div><div class="role-card-footer"><span>${Object.entries(SKILLS).find(([key])=>b.skills[key]===80)[1].name} <b>80</b></span><span>${fmt(b.cash)}</span></div><div class="role-pool">开局旧识 ${STARTER_COUNTS[id]} 人 · 已签订单 0</div></label>`).join('')}</fieldset><div id="role-detail" class="role-detail" aria-live="polite"></div><div class="selection-bottom"><span class="meta">四项能力均可成长 · 岗位决定起点，路线由你选择</span><div class="modal-actions">${hasSave?'<button type="button" class="secondary" data-do="continue-save">继续原来的公司</button>':''}<button type="button" class="primary" data-do="setup-next" id="role-next">选择开发，继续</button></div></div></section><section id="identity-step" hidden><div class="identity-grid"><div><fieldset class="gender-options"><legend>选择你的性别与形象</legend><div class="gender-row">${[['male','男性'],['female','女性']].map(([id,label])=>`<label class="gender-choice"><input type="radio" name="gender" value="${id}" ${id==='male'?'checked':''} required>${portrait(id)}<span>${label}</span></label>`).join('')}</div><p class="meta">头像随性别变化，能力和启动资金由岗位决定。</p></fieldset><label class="field-label" for="name">给公司取个名字</label><input id="name" class="input" name="company" maxlength="24" required value="独立造物工作室"><label class="field-label" for="previous-salary">离职前的月薪（本局目标基准）</label><input class="input" id="previous-salary" name="salary" type="number" min="3000" max="50000" step="1" value="12000" data-setting required><p class="meta">游戏默认值，可按自己的目标调整。开局后锁定；每月按 28 天计算，最终目标为此金额的两倍。</p><p class="identity-prologue">星期一，你不再打卡。没有晨会，也没有人替你决定今天做什么。你给自己一年时间，从一张书桌开始，建立一家属于自己的公司。</p></div><aside class="origin-card" id="origin-preview" aria-live="polite"></aside></div><div class="setup-bottom"><p class="meta">${hasSave?'确认开始后会替换当前存档，返回选择不会丢失填写内容。':'每周固定开销 ¥850 · 每天两件事 · 一年 52 周'}</p><div class="modal-actions"><button type="button" class="secondary" data-do="setup-back">返回选择岗位</button><button class="primary" type="submit">开启我的创业故事</button></div></div></section></form>`);modal.classList.add('setup-modal');updateOrigin()}
function switchSetup(step){setupStep=step;document.querySelector('#career-step').hidden=step!==1;document.querySelector('#identity-step').hidden=step!==2;document.querySelector('#setup-title').textContent=step===1?'选择你的职业起点':'让这个故事，属于你';document.querySelector('#setup-subtitle').textContent=step===1?'你擅长的事，是这家公司的第一笔资产。':'选好形象，为你的第一家公司取个名字。';document.querySelector('#step-one').classList.toggle('current',step===1);document.querySelector('#step-two').classList.toggle('current',step===2);document.querySelector('#step-one').setAttribute('aria-current',step===1?'step':'false');document.querySelector('#step-two').setAttribute('aria-current',step===2?'step':'false');modal.scrollTop=0;document.querySelector('#setup-title').focus()}
function updateOrigin(){const form=document.querySelector('#setup');if(!form)return;const data=new FormData(form),b=BACKGROUNDS[data.get('background')];document.querySelector('#role-detail').innerHTML=`<div class="role-description"><span class="eyebrow">YOUR ADVANTAGE</span><h3>${b.strength}</h3><p>${b.tradeoff}</p></div><div class="selection-skill-grid">${Object.entries(SKILLS).map(([id,k])=>`<div><div class="flex"><span>${k.name}</span><b>${b.skills[id]}</b></div><div class="progress-track"><i style="width:${b.skills[id]}%"></i></div></div>`).join('')}</div>`;document.querySelector('#role-next').textContent='选择'+b.name+'，继续';document.querySelector('#origin-preview').innerHTML=`<span class="eyebrow">YOUR FIRST CHAPTER</span><div class="origin-heading">${portrait(data.get('gender'),'small')}<h3>${b.name}的第一天</h3></div><p>${b.story}</p><div class="origin-budget">${fmt(b.cash)} <span>约 ${Math.floor(b.cash/850)} 周固定开销</span></div><small>交付 / 8 小时 ${effects({skills:b.skills}).delivery} 标准工时 · 拓客 / 8 小时 ${effects({skills:b.skills}).prospect} 条线索<br>研发 / 8 小时 +${effects({skills:b.skills}).develop}% · 营销 / 8 小时 +${effects({skills:b.skills}).market} 触达</small>`}

function story(){const b=BACKGROUNDS[s.background];show(top('YOUR FIRST CHAPTER','你的创业起点')+`${s.gender?portrait(s.gender):''}<h3>${b.name}</h3><p>${b.story}</p><p>本局实际启动资金：${fmt(s.initialCash)}。${s.initialCash!==b.cash?'此为旧版存档，资金保留原值。':''}</p><div class="modal-actions"><button class="primary" data-do="close">继续经营</button></div>`)}
modal.addEventListener('cancel',e=>{if(!hasSave||chatBusy)e.preventDefault();else modal.classList.remove('setup-modal')});
document.addEventListener('change',e=>{if(e.target.closest('#setup')){if(e.target.name==='background')document.querySelector('#previous-salary').value=SALARY_PRESETS[e.target.value];updateOrigin();}if(e.target.id==='training-target'){try{setTraining(s,e.target.value);render()}catch(err){toast(err.message)}}});



function contactProfile(l){return CONTACTS.find(c=>c.id===l.profileId)||CONTACTS.find(c=>c.company===l.client)||CONTACTS[0]}
function profileCard(l,preview=false){const c=contactProfile(l);return `<button class="contact-card" ${preview?`data-start-contact="${l.id}"`:`data-accept="${l.id}"`}><span class="contact-avatar" style="background:${c.color}">${c.avatar}</span><span><strong>${c.name} <small>${c.role}</small></strong><span>${c.company} · ${c.industry}</span><p>${c.background}</p>${l.acquaintance?`<p class="positive">你们的关系：${esc(l.acquaintance)}</p>`:''}<em>${preview?'开始建立联系 · 消耗 8 小时':'打开聊天'}</em></span></button>`}
function openContacts(){
let selected=s.leads[0]?.id;
show(`<div class="wx-directory"><aside class="wx-rail"><span class="wx-self" aria-label="我的头像">${esc(s.name?.slice(0,1)||'我')}</span><span class="wx-rail-icon" aria-hidden="true">☏</span><span class="wx-rail-icon active" aria-label="通讯录">▣</span><span class="wx-rail-bottom" aria-hidden="true">☰</span></aside><section class="wx-list-pane"><div class="wx-search"><label class="sr-only" for="wx-search-input">搜索联系人</label><input id="wx-search-input" placeholder="搜索" type="search" autocomplete="off"><button data-branch="prospect" aria-label="添加新朋友" title="添加新朋友 · 消耗 8 小时" ${dayUsed(s)>=2||!s.contactPool?'disabled':''}>＋</button></div><div class="wx-list-title">通讯录 <span>${s.leads.length}</span></div><div id="wx-contact-list" class="wx-contact-list"></div><p class="wx-list-foot">聊天不消耗时段</p></section><section class="wx-detail-pane"><header class="wx-window-bar"><span>通讯录</span><button class="close" data-do="close" aria-label="关闭弹窗">×</button></header><div id="wx-contact-detail" class="wx-contact-detail"></div></section></div>`);
modal.classList.add('wechat-directory-modal');
const list=document.querySelector('#wx-contact-list'),detail=document.querySelector('#wx-contact-detail'),search=document.querySelector('#wx-search-input');
function draw(){const query=search.value.trim().toLowerCase(),matches=s.leads.filter(l=>{const c=contactProfile(l);return [c.name,c.company,c.role,c.industry].join(' ').toLowerCase().includes(query)});if(!matches.some(l=>l.id===selected))selected=matches[0]?.id;
list.innerHTML=matches.map(l=>{const c=contactProfile(l);return `<button class="wx-contact-row ${l.id===selected?'selected':''}" data-wx-person="${l.id}" aria-pressed="${l.id===selected}"><span class="contact-avatar" style="background:${c.color}">${esc(c.avatar)}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.company)}</small></span></button>`}).join('')||'<p class="wx-empty">没有找到联系人</p>';
const l=matches.find(l=>l.id===selected);if(!l){detail.innerHTML=`<div class="wx-empty-detail"><span>▣</span><p>${query?'试试姓名、公司或岗位关键词':'通讯录还是空的'}</p><small>${query?'':'点击左上角 ＋，结识新朋友'}</small></div>`;return}const c=contactProfile(l);
detail.innerHTML=`<div class="wx-profile"><div class="wx-profile-heading"><span class="contact-avatar" style="background:${c.color}">${esc(c.avatar)}</span><div><h2>${esc(c.name)}</h2><p>${esc(c.role)}</p><small>${esc(c.company)}</small></div></div><dl><div><dt>行业</dt><dd>${esc(c.industry)}</dd></div><div><dt>备注</dt><dd>${esc(l.acquaintance||'新认识的朋友')}</dd></div><div><dt>个人介绍</dt><dd>${esc(c.background)}</dd></div><div><dt>正在关注</dt><dd>${esc(l.title)}</dd></div></dl><button class="wx-message" data-accept="${l.id}">发消息</button><p class="wx-profile-hint">先聊聊近况，再看看能帮上什么忙。</p></div>`;
list.querySelectorAll('[data-wx-person]').forEach(btn=>btn.addEventListener('click',()=>{selected=s.leads.find(x=>String(x.id)===btn.dataset.wxPerson)?.id;draw()}));}
search.addEventListener('input',draw);draw();
}
function openBranch(id){if(id==='develop'&&!s.productPlan){if(s.ended)return ending();if(s.pendingEvent)return event();return openProductPlan()}if(s.ended)return ending();if(s.pendingEvent)return event();const a=ACTIONS.find(a=>a.id===id);if(!a)return;let body='';if(id==='prospect'){const preview=structuredClone(s);preview.leads=preview.leads.filter(l=>l.expires>s.week);const count=Math.min(s.contactPool,effects(s).prospect,12-preview.leads.length),candidates=[];for(let i=0;i<count;i++)candidates.push(makeLead(preview,(s.week+i+preview.nextId)%6));body=`<p>你可以从这些人开始。点击任意一位，将这批 ${count} 位潜客加入通讯录并开始聊天，共消耗 8 小时。合作机会取决于真实需求、对方权限和沟通建立的关系。</p><div class="contact-cards">${candidates.map(l=>profileCard(l,true)).join('')||'<div class="empty">暂时没有可拓展的联系人。可以用内容营销获取咨询，或联系通讯录中的客户。</div>'}</div><div class="modal-actions"><button class="secondary" data-contacts>打开已有通讯录</button></div>`}
else if(id==='delivery'){body=`${clientTaskCards()}<h3>已签约 · 正式交付</h3><p>选择一个客户任务交给 Agent 协助推进。投入 8 小时，按你的交付能力与精力计算完成量。</p>${s.projects.map(p=>`<button class="choice" data-execute="delivery" data-target="${p.id}">${esc(p.title)}<small>${p.progress} / ${p.hours} 标准工时 · 第 ${p.due} 周到期</small></button>`).join('')||'<div class="empty">暂无已签约订单。售前 Demo 请在上方处理。</div>'}`}
else if(id==='train'){body=`<p>这次想补足哪项能力？一次学习消耗 8 小时，能力提升 4 点，上限 100。</p>${Object.entries(SKILLS).map(([key,k])=>`<button class="choice" data-execute="train" data-target="${key}" ${s.skills[key]===100?'disabled':''}>${k.name}<small>当前 ${s.skills[key]} · ${k.desc}</small></button>`).join('')}`}
else if(id==='develop'){body=`<h3>${esc(s.productPlan.direction)}</h3>${productSummary()}<p>目标用户：${esc(s.productPlan.audience)}</p><p>场景：${esc(s.productPlan.scenario)}</p><p>解决方式：${esc(s.productPlan.solution)}</p><p>售价 ${fmt(s.productPlan.price)} / 份 · 研发进度 ${s.product}%</p><div class="modal-actions">${s.productDemo?'<button class="secondary" data-preview-demo>打开 Demo</button>':''}<button class="secondary" data-edit-product>修改方案并重新开发</button><button class="primary" data-execute="develop" ${s.product===100?'disabled':''}>继续研发 · 8 小时</button></div>`}
else if(id==='market'){body=`<p>把你的经验写成一篇公众号文章，让可能需要你的人看见。发布消耗 8 小时，增加触达并带来咨询。</p><form id="marketing-form"><p class="meta">今天剩余 ${Math.max(0,2-dayUsed(s))} 个时段 · 发布需要 1 个时段</p><label class="field-label" for="post-title">文章标题</label><input class="input" id="post-title" required maxlength="80" placeholder="给这篇文章起个标题"><label class="field-label" for="post-content">正文</label><textarea class="input" id="post-content" rows="5" required minlength="5" maxlength="1500" placeholder="分享一个你解决过的问题，说明你能帮助哪些人…"></textarea><div id="marketing-error" class="negative" role="alert">${dayUsed(s)>=2?'今天的两个时段已用完，请先返回工作室结束今天，明天再发布。':''}</div><div class="modal-actions"><button class="secondary" type="button" data-do="close">返回工作室</button><button class="primary" type="submit">发布公众号文章 · 8 小时</button></div></form>`}
else{const detail={develop:`当前研发进度 ${s.product}%，本次将推进 ${effects(s).develop}%。`,research:`梳理客户问题、访谈需求。当前需求匹配度 ${s.productFit}%，本次提高 ${effects(s).research} 点。`,rest:`离开工作台，让自己恢复一下。当前精力 ${s.energy}，本次恢复 18 点。`}[id];body=`<p>${detail}</p><div class="modal-actions"><button class="primary" data-execute="${id}" ${id==='develop'&&s.product===100?'disabled':''}>${id==='rest'?'去休息':id==='research'?'开展需求调研':'开始研发'} · 8 小时</button></div>`}show(top(id==='market'?'OFFICIAL ACCOUNT · 图文编辑':id==='delivery'?'VIBE CODING AGENT · 客户任务':'WORKSPACE',a.name)+body);modal.classList.add('chat-modal')}
function executeBranch(id,target,content,marketing){const notes=performAction(s,id,{marketing,target:id==='delivery'?Number(target):target,content});render();show(top('ACTION COMPLETE','这件事，完成了。')+`<div class="report-notes">${(notes.length?notes:['精力已恢复，可以继续经营。']).map(n=>`<div>${esc(n)}</div>`).join('')}</div><p>今天还可完成 ${2-dayUsed(s)} 件事。成果已生效，周结算不会重复执行。</p><div class="modal-actions">${id==='market'?'<button class="secondary" data-contacts>看看谁来咨询</button>':''}<button class="primary" data-do="close">返回工作室</button></div>`)}
function openCustomer(id,draft=''){const lead=s.leads.find(l=>l.id===id);if(!lead)return toast('客户线索已失效');chatLeadId=id;const c=contactProfile(lead),result=lead.evaluation,ended=['converted','rejected'].includes(lead.status),limit=(lead.conversation||[]).length>=16;show(`<div class="messenger"><aside class="messenger-contacts"><div class="messenger-brand">微信式客户沟通</div>${s.leads.map(l=>{const p=contactProfile(l);return `<button class="messenger-person ${l.id===id?'selected':''}" data-accept="${l.id}" ${chatBusy?'disabled':''}><span class="contact-avatar" style="background:${p.color}">${p.avatar}</span><span><strong>${p.name}</strong><small>${p.company}</small></span></button>`}).join('')}<button class="text-btn" data-contacts>全部联系人</button></aside><section class="messenger-chat"><div class="messenger-top"><div><strong>${c.name}</strong><span>${c.company} · ${c.role}</span></div><button class="close" data-do="close" aria-label="关闭弹窗">×</button></div><details class="customer-dossier" open><summary>客户资料 · ${c.industry}</summary><p>${c.background}</p>${lead.acquaintance?`<p>你们的关系：${esc(lead.acquaintance)}</p>`:''}<small>正在关注：${esc(lead.title)} · 预算 ${fmt(lead.price)} · ${lead.weeks} 周</small></details><div class="chat-log">${(lead.conversation||[]).map(m=>`<div class="chat-bubble ${m.role==='user'?'mine':''}"><small>${m.role==='user'?'我':c.name}</small><p>${esc(m.content)}</p>${m.attachment?`<button type="button" class="secondary" data-library-item="${esc(m.attachment.id)}">查看项目 · ${esc(m.attachment.title)}</button>`:''}</div>`).join('')||`<div class="chat-start">你已经添加了 ${c.name}，现在可以开始聊天了。</div>`}</div>${result?`<div class="relationship-note">${esc(lead.relationship?.stage||'沟通反馈')} · ${esc(lead.relationship?.hint||result.advice||'继续了解对方的需求')}</div>`:''}${lead.status==='converted'?`<div class="wechat-opportunity"><strong>对方愿意进一步合作</strong><p>项目 ${esc(lead.title)} · 总额 ${fmt(lead.price)}</p><button class="primary" data-confirm-accept="${lead.id}" ${s.projects.length>=3?'disabled':''}>确认合作并收取预付款</button></div>`:ended||limit?'<div class="relationship-note">本轮沟通结束，可以联系其他潜客。</div>':`<form id="chat-form" class="wechat-composer"><label class="sr-only" for="customer-message">给客户发消息</label><textarea id="customer-message" maxlength="1000" rows="3" placeholder="轻松聊聊：你能帮什么忙？可以先做个小样看看…">${esc(draft||(!(lead.conversation||[]).length?s.openingPitch:''))}</textarea><label class="sr-only" for="chat-project">附带项目</label><select class="input" id="chat-project"><option value="">附带项目：不选择</option>${projectLibrary(s).map(p=>`<option value="${esc(p.id)}">${esc(p.title)} · ${esc(p.status)}</option>`).join('')}</select><div id="chat-error" class="negative" role="alert"></div><button type="button" class="text-btn" data-record-client-demo>登记 Demo 承诺</button><button type="button" class="text-btn" data-new-appointment>登记约定时间</button><div class="flex"><a href="/admin.html" target="_blank" rel="noopener">DeepSeek 设置</a><button class="wechat-send" id="send-customer" type="submit">发送</button></div></form>`}</section></div>`);modal.classList.add('messenger-modal');const log=document.querySelector('.chat-log');if(log)log.scrollTop=log.scrollHeight}
async function sendCustomer(){if(chatBusy)return;const lead=s.leads.find(l=>l.id===chatLeadId),input=document.querySelector('#customer-message');if(!lead||!input)return;const attachment=projectLibrary(s).find(p=>p.id===document.querySelector('#chat-project')?.value);const message=[input.value.trim(),attachment?projectMessage(attachment):''].filter(Boolean).join('\n\n');if(message.length<5){document.querySelector('#chat-error').textContent='请输入至少 5 个字，或选择一个项目发送。';return}if(message.length>2000){document.querySelector('#chat-error').textContent='附带项目后消息过长，请缩短文字。';return}chatBusy=true;const button=document.querySelector('#send-customer');button.disabled=true;button.textContent='客户正在思考…';document.querySelector('#chat-error').textContent='';try{if(location.protocol==='file:')throw Error('客户对话需要本地服务，请通过 http://127.0.0.1:4173 打开游戏。');const r=await fetch('/api/customer-chat',{method:'POST',headers:{'Content-Type':'application/json','X-Solo-Local':'1'},body:JSON.stringify({campaignId:s.campaignId,lead:{acquaintance:lead.acquaintance||'',id:lead.id,profileId:lead.profileId,client:lead.client,title:lead.title,price:lead.price,hours:lead.hours,weeks:lead.weeks},skills:s.skills,message,history:lead.conversation||[]}),signal:AbortSignal.timeout(85000)});const result=await r.json();if(!r.ok)throw Error(result.error||'客户暂时没有回复');applyConversation(s,lead.id,message,result);if(attachment){lead.conversation[lead.conversation.length-2].attachment={id:attachment.id,title:attachment.title};markClientDemoSent(s,lead.id,attachment.id);}save();chatBusy=false;render();openCustomer(lead.id)}catch(err){chatBusy=false;const errorBox=document.querySelector('#chat-error');if(errorBox)errorBox.textContent=(err.name==='TimeoutError'?'等待客户回复超时。':err instanceof TypeError?'无法连接本地服务，请确认服务已启动。':err.message)+' 消息已保留，本轮未计入沟通，可重新发送。';button.disabled=false;button.textContent='重新发送'}}
function help(){show(top('HOW TO PLAY','一个人，经营一整家公司。')+'<ul><li>开局按职业获得 5–10 位旧识联系人，可在微信或 SCRM 中直接跟进。认识不等于成交，沟通后才能形成合作；也可继续拓客或发布内容。</li><li>后台配置密钥后可聊天。后台综合匹配度、决策能力、亲密度与对话质量决定机会，签约收 30% 预付款。</li><li>每天最多完成两件事。点击行动按钮进入分支，确认后立即执行，每次 8 小时。每天结束检查到期承诺，第七天结算固定开销。四项能力最高 100。</li><li>交付能力提高项目与研发效率；客户洞察提高调研与研发效率。</li><li>内容创作提高营销触达；拓客沟通提高新线索数量及报价。已有合同不重新定价。</li><li>相关工作每时段提升对应能力 1 点；专项学习每时段提升指定能力 4 点。</li><li>需求匹配度初始 30，调研可提升到 100。匹配度、转化价值、触达、信誉和定价共同影响每日销量；过高定价会降低购买率。</li><li>点击项目交付，选择要推进的订单，完成即收尾款。自动化工具优先处理最早到期的订单。</li><li>项目逾期会扣信誉；再过两周仍未完成，将退款取消。</li><li>产品方案须经 LLM 评估，转化价值和用户匹配度均达到 60 分，研发至 100% 后才从次日自动销售，无需逐单沟通。营销扩大触达，提高销量。</li><li>精力低于 45 时交付效率降为 75%，低于 25 时降为 50%。休息可以恢复。</li><li>每周扣除 ¥850 固定开销，现金为负则结束。五个里程碑依次完成才算胜利：首单全款、月入原薪、7 天自动成交、28 天自动收入超过原薪、达到原薪两倍。第 52 周仍未达成则本局挑战结束。</li></ul><p>当前进度只保存在此浏览器。左下角头像可以命名公司并选择背景，开启新的一局。</p><div class="modal-actions"><button class="primary" data-do="close">开始经营</button></div>')}
function changeView(v){if(!['overview','orders','product','finance'].includes(v))return;view=v;render()}
function finishWeek(){if(s.ended)return ending();if(s.pendingEvent)return event();if(!used(s)){show(top('A QUIET WEEK','让自己休息一周？')+'<p>本周没有安排工作。精力将恢复 20 点，固定开销仍会正常扣除。</p><div class="modal-actions"><button class="secondary" data-do="close">返回安排</button><button class="primary" data-do="force-advance">休息并结算</button></div>');return}doAdvance()}
function doAdvance(){const r=advance(s);render();report(r)}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(chatBusy){toast('客户正在回复，请稍候');return}try{if(b.dataset.journey!==undefined){openJourney();return;}if(b.dataset.pickName){const form=b.closest('form'),input=form.querySelector('[name=username]');input.value=b.dataset.pickName;form.querySelectorAll('[role=alert]').forEach(n=>n.textContent='');input.focus();return;}if(b.dataset.shuffleNames!==undefined){refreshNames(b.closest('form'));return;}if(b.id==='leaderboard'||b.dataset.rankMetric!==undefined){openLeaderboard(b.dataset.rankMetric||'income');return}if(b.id==='user-manager'||b.dataset.openUsers!==undefined){openUserManager();return}if(b.dataset.switchUser){switchUser(b.dataset.switchUser);return}if(b.id==='game-settings'){openGameSettings();return}if(b.dataset.gameMode){gameMode=b.dataset.gameMode==='simple'?'simple':'simulation';try{localStorage.setItem(MODE_KEY,gameMode)}catch{}updateModeLabel();openGameSettings();toast('已切换为'+(gameMode==='simple'?'简单':'仿真')+'模式');return}if(b.dataset.simpleRetry!==undefined){generateSimpleChoices(b.closest('form'));return}if(b.dataset.simpleOption!==undefined){if(e.target.closest('details'))return;const form=b.closest('form'),state=simpleForms.get(form),choice=state?.choices[Number(b.dataset.simpleOption)];if(!choice)return;for(const input of state.inputs){input.value=choice.values[input.id||input.name]??'';}state.selected=true;state.submit.forEach(button=>button.disabled=false);state.mount.querySelectorAll('[data-simple-option]').forEach(button=>{button.classList.toggle('selected',button===b);button.setAttribute('aria-pressed',String(button===b));});return}if(b.dataset.clientTask){openClientTask(b.dataset.clientTask);return}if(b.dataset.sendClientDemo){sendClientDemo(b.dataset.sendClientDemo);return}if(b.dataset.recordClientDemo!==undefined){recordManualDemo();return}if(b.dataset.walletFilter){walletFilter=b.dataset.walletFilter;render();return}if(b.dataset.walletBill!==undefined){openBill(Number(b.dataset.walletBill));return}if(b.dataset.newAppointment!==undefined){openAppointment();return}if(b.dataset.fulfill){fulfillAppointment(s,b.dataset.fulfill);render();close();toast('约定已完成，占用今天一件事');return}if(b.dataset.nextDay!==undefined){const result=nextDay(s);render();close();if(s.ended)ending();else if(result.report)report(result.report);else if(result.notes.length)show(top('DAY REPORT','今天的经营记录')+result.notes.map(n=>'<p>'+esc(n)+'</p>').join(''));return}if(b.dataset.scrmFilter!==undefined){openSCRM(b.dataset.scrmFilter);return}if(b.dataset.workspace==='scrm'){openSCRM();return}if(b.dataset.workspace){openWorkspace(b.dataset.workspace);return}if(b.dataset.reading!==undefined){openReading(Number(b.dataset.reading));return}if(b.dataset.library!==undefined){openLibrary();return}if(b.dataset.libraryItem){openLibraryItem(b.dataset.libraryItem);return}if(b.dataset.previewDemo!==undefined){openDemo();return}if(b.dataset.editProduct!==undefined){openProductPlan();return}if(b.dataset.confirmProduct!==undefined){confirmProduct(s,productProposal);s.productDraft=null;productProposal=null;render();openBranch('develop');return}if(b.dataset.view){changeView(b.dataset.view);return}if(b.dataset.contacts!==undefined){openContacts();return}if(b.dataset.branch){openBranch(b.dataset.branch);return}if(b.dataset.execute){executeBranch(b.dataset.execute,b.dataset.target);return}if(b.dataset.startContact){const id=Number(b.dataset.startContact);performAction(s,'prospect');render();openCustomer(id);return}if(b.dataset.accept){openCustomer(Number(b.dataset.accept));return}if(b.dataset.confirmAccept){accept(s,Number(b.dataset.confirmAccept));close();render();toast('合作达成！预付款已到账，记得安排项目交付。');return}if(b.dataset.buy){const t=TOOLS.find(t=>t.id===b.dataset.buy);show(top('WORK SMARTER',t.name)+`<p>${t.desc}</p><p>即刻支付 ${fmt(t.cost)}${t.weekly?'，之后每周扣除 '+fmt(t.weekly):'，无后续周费'}。</p><div class="modal-actions"><button class="secondary" data-do="close">暂不购买</button><button class="primary" data-confirm-buy="${t.id}">确认购买</button></div>`);return}if(b.dataset.confirmBuy){buy(s,b.dataset.confirmBuy);close();render();toast('工具已启用');return}if(b.dataset.event){resolveEvent(s,b.dataset.event);close();render();toast('决定已记录，继续你的创业旅程。');return}if(b.id==='help'){help();return}if(b.id==='new-game'){newGame();return}if(b.id==='calendar'||b.dataset.openCalendar!==undefined){show(top('MY CALENDAR','工作与承诺')+calendarPanel());modal.classList.add('chat-modal');return}switch(b.dataset.do){case'setup-next':switchSetup(2);break;case'setup-back':switchSetup(1);break;case'story':story();break;case'continue-save':s.founderConfigured=true;close();render();if(!hasSave||!s.founderConfigured)newGame();else if(s.pendingEvent)event();break;case'close':close();break;case'advance':endToday();break;case'force-advance':doAdvance();break;case'after-report':close();if(s.ended)ending();else if(s.pendingEvent)event();else {const l=s.leads.find(l=>['new','followup'].includes(l.status));if(l)openCustomer(l.id)}break;case'new':newGame();break}}catch(err){toast(err.message)}});
document.addEventListener('submit',e=>{if(['create-user-form','rename-user-form','register-user-form'].includes(e.target.id)){e.preventDefault();try{if(userStorageError)throw Error(userStorageError);const name=new FormData(e.target).get('username');if(e.target.id==='create-user-form'){const user=createUser(localStorage,name);switchUser(user.id);}else{activeUser=renameUser(localStorage,activeUser.id,name);render();if(e.target.id==='register-user-form'){modal.close();newGame();}else openUserManager();}}catch(error){e.target.querySelector('[role=alert]').textContent=error.message;}return}if(e.target.id==='client-demo-form'){e.preventDefault();buildClientDemo(e.target);return}if(e.target.id==='appointment-form'){e.preventDefault();try{const data=new FormData(e.target);addAppointment(s,{title:String(data.get('title')),client:String(data.get('client')),due:(Number(data.get('week'))-1)*7+Number(data.get('day')),penalty:Number(data.get('penalty'))});render();close();toast('约定已加入日程表')}catch(error){toast(error.message)}return}if(e.target.id==='product-plan-form'){e.preventDefault();assessProduct(e.target);return}if(e.target.id==='marketing-form'){e.preventDefault();publishMarketing(e.target);return}if(e.target.id==='pitch-form'){e.preventDefault();s.openingPitch=document.querySelector('#opening-pitch').value.trim();save();close();toast('开场白已保存，结算本周后与客户沟通');return}if(e.target.id==='chat-form'){e.preventDefault();sendCustomer();return}if(e.target.id!=='setup')return;e.preventDefault();if(setupStep===1){switchSetup(2);return}const data=new FormData(e.target);const name=String(data.get('company')).trim();if(!name){toast('请填写公司名称');return}try{s=initial(name,String(data.get('background')),String(data.get('gender')),Number(data.get('salary')));}catch(error){toast(error.message);return;}hasSave=true;view='overview';close();render();toast('公司成立了，你的第一年现在开始。')});
render();if(!hasSave||!s.founderConfigured)newGame();else if(s.pendingEvent)event();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_company_state',title:'查看公司经营状态',description:'Read this browser’s current solo company game state without advancing time.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object');return structuredClone({week:s.week,cash:s.cash,energy:s.energy,reputation:s.reputation,plan:s.plan,projects:s.projects,product:s.product,ended:s.ended})}})).catch(()=>{})}catch{}}

let productProposal=null;
function productSummary(){const e=s.productEvaluation;if(!e)return '';return `<div class="fit-box"><strong>${e.canMonetize?'具备变现潜力':'暂不具备变现条件'}</strong><p>转化价值 ${e.conversion} / 100 · 用户匹配度 ${e.fit} / 100</p><p>${esc(e.summary)}</p><p>改进建议：${esc(e.suggestion)}</p></div>`}
function openProductPlan(){productProposal=null;const p=s.productDraft||s.productPlan||{};show(top('PRODUCT LAB','定义你的产品')+`<p>每项用一两句话说明即可。点击开发，用 AI 编写可交互 Demo。成功后消耗 8 小时和 ¥300 游戏资金，失败不扣除。</p><form id="product-plan-form">${[['direction','产品方向','例如：给小店用的预约小工具'],['audience','目标用户','例如：独立美甲店店主'],['scenario','使用场景','例如：每天在微信中反复确认预约时间'],['solution','解决方式','例如：顾客自选时段，店主收到预约提醒']].map(([k,label,placeholder])=>`<label class="field-label" for="product-${k}">${label}</label><textarea class="input" id="product-${k}" name="${k}" rows="2" required minlength="2" maxlength="600" placeholder="${placeholder}">${esc(p[k]||'')}</textarea>`).join('')}<label class="field-label" for="product-price">定价（元 / 份，一次性购买）</label><input class="input" id="product-price" name="price" type="number" min="1" max="100000" step="0.01" required value="${p.price||99}"><p class="meta">转化价值和用户匹配度均达到 60 分，研发完成后才会产生销量。重新开发成功后会重置现有研发进度和该产品销量，历史收入保留。开发会使用你的 DeepSeek API 额度。</p><div id="product-error" class="negative" role="alert"></div><div class="modal-actions"><button class="primary" id="evaluate-product" type="submit">开发 Demo · 8 小时 / ¥300</button></div></form>`);modal.classList.add('chat-modal')}
async function assessProduct(form){if(chatBusy)return;if(s.ended||s.pendingEvent||dayUsed(s)>=2||s.cash<300){document.querySelector('#product-error').textContent='开发需要剩余 8 小时和 ¥300 游戏资金，请先处理经营事件或结算。';return}const data=new FormData(form),plan=Object.fromEntries(['direction','audience','scenario','solution'].map(k=>[k,String(data.get(k)).trim()]));plan.price=Number(data.get('price'));s.productDraft=plan;save();show(top('VIBE CODING','Demo 开发中')+`<div class="demo-building"><div class="demo-spinner"></div><h3>正在把你的想法写成代码</h3><p>${esc(plan.direction)}</p><p>DeepSeek 正在评估方案并编写界面与交互，通常需要一两分钟；若输出过长，会自动精简重试，请稍候。</p><p class="meta">完成后消耗 8 小时与 ¥300 游戏资金。请保持页面打开；失败不扣除。</p></div>`);chatBusy=true;try{const response=await fetch('/api/product-demo',{method:'POST',headers:{'Content-Type':'application/json','X-Solo-Local':'1'},body:JSON.stringify({plan}),signal:AbortSignal.timeout(310000)});const result=await response.json();if(!response.ok)throw Error(result.error||'Demo 开发失败');completeDemo(s,result);chatBusy=false;render();openDemo()}catch(error){chatBusy=false;openProductPlan();document.querySelector('#product-error').textContent=(error.name==='TimeoutError'?'开发等待超时，请重试。':error.message)+' 本次未扣游戏时间和资金，方案草稿已保留。'}}
function openDemo(){if(!s.productDemo)return;show(top('DEMO READY','你的 Demo 已完成')+`<p>${esc(s.productPlan.direction)} · 本次开发 8 小时 / ¥300</p>${productSummary()}<p class="meta">下面是 AI 编写的交互原型，使用演示数据。Demo 完成不代表正式上线，继续研发至 100% 后按评估结果销售。</p><iframe id="product-demo-frame" title="产品 Demo 交互预览" sandbox="allow-scripts" referrerpolicy="no-referrer" style="width:100%;height:480px;border:0;border-radius:12px;background:white"></iframe><div class="modal-actions"><button class="secondary" data-edit-product>修改方案重新开发</button><button class="secondary" data-library>我的项目库</button><button class="primary" data-branch="develop">返回研发</button></div>`);modal.classList.add('chat-modal');const csp="<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src data:; connect-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'none'\">";document.querySelector('#product-demo-frame').srcdoc=csp+s.productDemo.html;}

function openLibrary(){show(top('MY PROJECTS','我的项目库')+'<p>Demo 和已交付项目自动归档，重新开发不会覆盖旧版本。在客户聊天框中选择「附带项目」即可发送，客户会根据作品说明回应。</p><div class="project-list">'+projectLibrary(s).map(p=>`<button class="choice" data-library-item="${esc(p.id)}">${esc(p.title)}<small>${esc(p.kind)} · ${esc(p.status)} · 第 ${p.week} 周</small></button>`).join('')+(projectLibrary(s).length?'':'<div class="empty">项目库还是空的，先开发一个 Demo 或承接客户项目。</div>')+'</div>');}
function openLibraryItem(id){const item=projectLibrary(s).find(p=>p.id===id);if(!item)return toast('项目暂不可用');show(top('PROJECT DETAIL',esc(item.title))+`<p>${esc(item.kind)} · ${esc(item.status)}</p><p style="white-space:pre-wrap">${esc(projectMessage(item))}</p>${item.html?'<iframe id="library-demo" title="项目库 Demo 预览" sandbox="allow-scripts" referrerpolicy="no-referrer" style="width:100%;height:480px;border:0;background:white;border-radius:12px"></iframe>':''}<div class="modal-actions"><button class="secondary" data-library>返回项目库</button>${chatLeadId&&s.leads.some(l=>l.id===chatLeadId)?`<button class="primary" data-accept="${chatLeadId}">返回客户沟通</button>`:''}</div>`);modal.classList.add('chat-modal');if(item.html)document.querySelector('#library-demo').srcdoc=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; font-src data:; connect-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'none'">`+item.html;}

function desktopApps(){const disabled=s.ended||s.pendingEvent?'disabled':'';return `<div class="workstation-scene ${s.gender==='female'?'workstation-female':'workstation-male'}">${deskSchedule()}<div class="room-window" aria-hidden="true"><i></i><i></i><i></i></div><div class="room-light" aria-hidden="true"></div><div class="desk-label">SOLO STUDIO <span>第 ${s.week} 周 · 第 ${s.day||1} 天</span></div><div class="computer"><div class="computer-camera"></div><div class="computer-screen"><div class="os-bar"><strong>◈ SOLO OS</strong><span>我的工作空间</span><span>今日 ${2-dayUsed(s)} / 2 个空闲时段</span></div><div class="os-desktop"><button class="screen-window screen-wechat" data-workspace="wechat" ${disabled} aria-label="打开微信"><span class="window-toolbar"><i class="window-dots">● ● ●</i><b>微信</b><em>↗</em></span><span class="wechat-preview"><span class="preview-contacts">${s.leads.slice(0,3).map(l=>`<span><i>${esc(contactProfile(l).avatar)}</i>${esc(contactProfile(l).name)}</span>`).join('')||'<span>通讯录</span><span>新的朋友</span>'}</span><span class="preview-chat"><b>客户消息</b><span class="preview-bubble">有空聊聊合作吗？</span><span class="preview-bubble mine">我做了一个 Demo，给你看看。</span><small>${s.leads.length} 位联系人 · 点击打开聊天</small></span></span></button><button class="screen-window screen-agent" data-workspace="agent" ${disabled} aria-label="打开 Vibe Coding Agent"><span class="window-toolbar"><i class="window-dots">● ● ●</i><b>Vibe Coding Agent</b><em>↗</em></span><span class="editor-tabs">workspace / <b>my-project</b></span><span class="editor-code"><span><i>01</i> <b>const</b> idea = <em>"${esc((s.productPlan?.direction||'把想法做出来').slice(0,22))}"</em>;</span><span><i>02</i> <b>await</b> agent.build(idea);</span><span><i>03</i> preview.<b>open</b>();</span></span><span class="editor-terminal">❯ Agent ready <i class="terminal-cursor"></i><small>${s.projects.length} 个客户项目 · 产品进度 ${s.product}%</small></span></button><button class="screen-window screen-article" data-workspace="article" ${disabled} aria-label="写公众号文章"><span class="window-toolbar"><i class="window-dots">● ● ●</i><b>公众号 · 图文编辑</b><em>↗</em></span><span class="paper-preview"><small>草稿箱 / 新建图文</small><strong>把今天的经验，写给需要的人。</strong><span class="paper-line"></span><span class="paper-line short"></span><span class="paper-publish">开始写作 →</span></span></button><button class="desktop-scrm" data-workspace="scrm" aria-label="打开 SCRM 客户管理"><span>客</span><b>SCRM</b><small>${s.leads.filter(l=>!['rejected','converted'].includes(l.status)).length} 位待跟进 · ${s.projects.length} 个合作中</small></button><button class="desktop-folder" data-workspace="reading" ${disabled} aria-label="看资料"><span>▰</span><b>资料夹</b><small>访谈 / 定价 / 产品</small></button></div><div class="os-dock">${[['wechat','聊','微信'],['scrm','客','SCRM'],['agent','>_','Agent'],['article','文','公众号'],['reading','▰','资料'],['learning','学','学习'],['break','☕','休息']].map(([id,mark,name])=>`<button data-workspace="${id}" ${disabled} aria-label="${name}" class="dock-${id}"><span>${mark}</span><small>${name}</small></button>`).join('')}</div></div><div class="monitor-chin">S O L O</div><div class="monitor-neck"></div><div class="monitor-foot"></div></div><div class="desk-surface" aria-hidden="true"></div><div class="desk-keyboard" aria-hidden="true">${'<i></i>'.repeat(42)}</div><div class="desk-mouse" aria-hidden="true"></div><button class="desk-coffee" data-workspace="break" ${disabled} aria-label="喝杯咖啡，休息一下"><span></span></button><button class="desk-notebook" data-workspace="learning" ${disabled} aria-label="打开学习笔记">IDEAS<br><small>我的学习笔记</small></button><div class="founder-at-desk ${s.gender==='female'?'female':''}" aria-hidden="true"><div class="founder-head"></div><div class="founder-neck"></div><div class="founder-body"></div><div class="founder-chair"></div></div><div class="scene-instruction">点击电脑上的窗口开始工作 · 打开工具不消耗时间</div></div>`}

function openWorkspace(id){if(s.ended)return ending();if(s.pendingEvent)return event();if(id==='wechat'){openContacts();return}if(id==='article'){openBranch('market');return}if(id==='reading'){show(top('READING ROOM','今天，看点什么？')+`<p>这是你的资料夹。选择一份经营笔记，读完后再决定是否投入时间整理洞察。</p>${[['用户访谈摘录','小店老板为什么不愿意换工具？'],['定价观察','用户愿意为省下的时间付多少钱？'],['产品体验笔记','从第一次打开到第一次完成任务']].map(([kind,title],i)=>`<button class="choice" data-reading="${i}">${title}<small>${kind} · 模拟经营资料</small></button>`).join('')}`);return}if(id==='learning'){openBranch('train');return}if(id==='break'){openBranch('rest');return}show(top('VIBE CODING AGENT','你的开发工作台')+`<div class="agent-terminal"><span class="agent-dot"></span> Agent ready <span class="meta">/ workspace</span><p>今天想把哪个想法做出来？</p></div><div class="agent-task-grid"><button class="choice" data-branch="develop">开发自己的产品<small>${esc(s.productPlan?.direction||'从一句想法开始，生成可交互 Demo')} · 当前进度 ${s.product}%</small></button><button class="choice" data-branch="delivery">推进客户项目<small>${clientTasks(s).filter(t=>t.status==='pending').length} 个 Demo 承诺 · ${s.projects.length} 个签约项目</small></button><button class="choice" data-library>打开项目库<small>预览 Demo，查看作品与交付记录</small></button></div><p class="meta">打开工具不消耗时间。执行开发或交付时消耗 8 小时；新 Demo 另需 ¥300 游戏资金。</p>`);modal.classList.add('chat-modal')}
function openReading(index){const readings=[{title:'小店老板为什么不愿意换工具？',text:'访谈摘录：我不是缺一个功能更多的软件，我是怕员工又得重新学。预约现在虽然麻烦，但大家都会用微信。',note:'用户同时考虑学习成本和切换成本。下一次聊需求时，先问现有工作怎么完成，再找最麻烦的一步。'},{title:'用户愿意为省下的时间付多少钱？',text:'观察记录：同样是节省一小时，有的人把它当作便利，有的人能用它多接一位客户。付费意愿取决于具体使用场景。',note:'把定价和可感知的收益联系起来。尝试问用户：如果这个问题解决了，你会把时间用在哪里？'},{title:'从第一次打开到第一次完成任务',text:'体验笔记：一个功能齐全的工具，如果第一次使用要填写太多资料，用户可能在看到价值前就离开了。',note:'让 Demo 先展示一个核心操作，用少量示例数据帮助用户立即理解。复杂设置可以放到后面。'}];const r=readings[index];if(!r)return;show(top('FIELD NOTES · 模拟经营资料',r.title)+`<div class="reading-paper"><span>独立经营者 / 阅读摘记</span><p>${r.text}</p><h3>可以带走的一个想法</h3><p>${r.note}</p></div><p class="meta">整理阅读笔记消耗 8 小时，运营需求匹配度 +${effects(s).research}（上限 100），不能替代产品变现评估。</p><div class="modal-actions"><button class="secondary" data-workspace="reading">返回资料夹</button><button class="primary" data-execute="research">整理洞察 · 8 小时</button></div>`)}

function calendarPanel(){const start=(s.week-1)*7;return `<section class="calendar-panel"><div class="section-heading"><h2>我的日程表</h2><button class="outline" data-new-appointment>登记约定</button></div><p class="meta">每天两件事 · 第 ${s.week} 周，第 ${s.day||1} 天 · 今天还可完成 ${2-dayUsed(s)} 件</p><div class="calendar-week">${Array.from({length:7},(_,i)=>{const d=start+i+1,items=agenda(s).filter(a=>a.due===d),actions=(s.dayHistory||[]).filter(a=>a.day===d);return `<div class="calendar-day ${d===today(s)?'today':''}"><strong>第 ${i+1} 天${d===today(s)?' · 今天':''}</strong>${[0,1].map(slot=>`<div class="calendar-slot ${actions[slot]?'filled':''}">${actions[slot]?esc(actions[slot].title):d<today(s)?'空闲':'待安排'}</div>`).join('')}${items.map(a=>`<span class="calendar-due ${a.status}">${esc(a.title)} · ${a.status==='done'?'已完成':a.status==='missed'||a.status==='overdue'?'已逾期':'到期'}</span>`).join('')}</div>`}).join('')}</div><div class="agenda-list">${agenda(s).filter(a=>a.status==='pending'||a.status==='overdue').sort((a,b)=>a.due-b.due).map(a=>`<div class="agenda-row"><div><strong>${esc(a.title)}</strong><small>${esc(a.client||'个人约定')} · 第 ${Math.ceil(a.due/7)} 周第 ${(a.due-1)%7+1} 天 · ${a.kind==='project'?'逾期信誉 -8；两周后取消并退预付款':'违约信誉 -5'+(a.penalty?'，赔付 '+fmt(a.penalty):'，无赔付')}</small></div>${a.kind==='client-demo'?`<button class="secondary" data-client-task="${a.id}">处理 Demo</button>`:a.kind==='project'?'<button class="secondary" data-branch="delivery">去交付</button>':`<button class="secondary" data-fulfill="${a.id}" ${dayUsed(s)>=2?'disabled':''}>完成约定</button>`}</div>`).join('')||'<p class="meta">目前没有待履行的约定。签约后交付截止日自动出现在这里。</p>'}</div><button class="primary week-button" data-do="advance">${s.pendingEvent?'处理经营事件':s.ended?'查看结局':s.day===7?'结束今天并结算本周':'结束今天，进入下一天'}</button></section>`}
function openAppointment(){const lead=s.leads.find(l=>l.id===chatLeadId);show(top('CALENDAR','把承诺放进日程')+`<p>确认双方约好的日期。完成约定占用当天一件事；结束到期日仍未完成会扣信誉和约定赔付。</p><form id="appointment-form"><label class="field-label" for="appointment-title">约定事项</label><input class="input" id="appointment-title" name="title" required minlength="2" maxlength="80" placeholder="例如：给客户演示 Demo"><label class="field-label" for="appointment-client">客户 / 联系人</label><input class="input" id="appointment-client" name="client" maxlength="80" value="${esc(lead?.client||'')}"><div class="flex"><div><label class="field-label">第几周<input class="input" name="week" type="number" min="${s.week}" max="52" value="${s.week}" required></label></div><div><label class="field-label">周内第几天<input class="input" name="day" type="number" min="1" max="7" value="${s.day||1}" required></label></div></div><label class="field-label" for="appointment-penalty">约定违约赔付（游戏资金，0 为不赔付）</label><input class="input" id="appointment-penalty" name="penalty" type="number" min="0" max="10000" step="1" value="0" required><div class="modal-actions"><button class="primary" type="submit">加入日程</button></div></form>`)}
function endToday(){if(s.ended)return ending();if(s.pendingEvent)return event();const due=agenda(s).filter(a=>a.status==='pending'&&a.due<=today(s));show(top('END OF DAY','结束今天？')+`<p>今天已完成 ${dayUsed(s)} / 2 件事。未用时段不会累积到明天。</p>${due.length?`<div class="negative">以下约定今天到期，继续将按日程规则处理违约：${due.map(a=>'<p>'+esc(a.title)+'</p>').join('')}</div>`:'<p>今天没有未完成的到期约定。</p>'}<div class="modal-actions"><button class="secondary" data-do="close">继续今天</button><button class="primary" data-next-day>确认结束今天</button></div>`)}

function clientTaskCards(){return `<h3>沟通承诺 · 客户 Demo</h3><p class="meta">售前承诺也会成为任务，不需要先签约。每个 Demo 开发消耗一天中的一个时段（8 小时）和 ¥300。</p>${clientTasks(s).map(t=>`<button class="choice" data-client-task="${t.id}">${esc(t.title)}<small>${esc(t.client)} · ${t.status==='ready'?'已完成，待发送':t.status==='sent'?'已发送':'待开发'}${t.due?' · 第 '+Math.ceil(t.due/7)+' 周第 '+((t.due-1)%7+1)+' 天到期':''}</small></button>`).join('')||'<p class="meta">暂无已识别的 Demo 承诺，可在微信里登记。</p>'}`}
function openClientTask(id){const t=clientTasks(s).find(t=>t.id===id);if(!t)return;if(t.status!=='pending'){show(top('CLIENT DEMO',esc(t.title))+`<p>${esc(t.client)} · ${t.status==='sent'?'已发送':'开发完成，等待发给客户'}</p><div class="modal-actions"><button class="secondary" data-library-item="${t.libraryId}">预览 Demo</button><button class="primary" data-send-client-demo="${t.id}">到微信发送</button></div>`);return}show(top('CLIENT DEMO','兑现给客户的 Demo 承诺')+`<p><strong>${esc(t.client)}</strong> · ${esc(t.title)}</p><p class="meta">承诺原文：${esc(t.promise)}</p><form id="client-demo-form" data-task="${t.id}"><label class="field-label" for="client-demo-brief">这次要演示什么？</label><textarea class="input" id="client-demo-brief" rows="5" minlength="2" maxlength="600" required>${esc(t.promise.slice(0,600))}</textarea><p class="meta">成功后消耗 8 小时和 ¥300，Demo 自动加入项目库。不会重置你自己的产品研发进度。</p><div id="client-demo-error" class="negative" role="alert"></div><button class="primary" type="submit">开发客户 Demo · 8 小时 / ¥300</button></form>`)}
async function buildClientDemo(form){if(chatBusy)return;const t=clientTasks(s).find(t=>t.id===form.dataset.task),brief=document.querySelector('#client-demo-brief').value.trim();if(!t)return;if(dayUsed(s)>=2||s.cash<300||s.pendingEvent||s.ended){document.querySelector('#client-demo-error').textContent='需要一个空闲时段和 ¥300，请先处理经营结果。';return}const lead=[...s.leads,...s.projects].find(l=>l.id===t.leadId);const plan={direction:t.title.slice(0,600),audience:t.client,scenario:('为客户验证「'+(lead?.title||t.title)+'」核心使用流程。客户需求：'+(lead?.conversation||[]).filter(m=>m.role==='assistant').slice(-2).map(m=>m.content).join('；')).slice(0,600),solution:brief,price:Math.max(1,Math.min(100000,lead?.price||99))};show(top('VIBE CODING','客户 Demo 开发中')+`<div class="demo-building"><div class="demo-spinner"></div><p>正在为 ${esc(t.client)} 编写可交互原型，请保持页面打开。</p><p class="meta">成功后扣除时间与费用；失败不扣游戏资源。</p></div>`);chatBusy=true;try{const response=await fetch('/api/product-demo',{method:'POST',headers:{'Content-Type':'application/json','X-Solo-Local':'1'},body:JSON.stringify({plan}),signal:AbortSignal.timeout(310000)});const result=await response.json();if(!response.ok)throw Error(result.error||'开发失败');completeClientDemo(s,t.id,result);chatBusy=false;render();openClientTask(t.id)}catch(error){chatBusy=false;openClientTask(t.id);document.querySelector('#client-demo-brief').value=brief;document.querySelector('#client-demo-error').textContent=(error.name==='TimeoutError'?'生成超时，请重试。':error.message)+' 本次未扣游戏资源。'}}
function sendClientDemo(id){const t=clientTasks(s).find(t=>t.id===id);if(!t)return;const lead=s.leads.find(l=>l.id===t.leadId);if(!lead||['converted','rejected'].includes(lead.status))return toast('该客户本轮沟通已结束，Demo 已保存在项目库。');openCustomer(lead.id,'这是我为你做的 Demo，可以先看看核心流程。');document.querySelector('#chat-project').value=t.libraryId;}
function recordManualDemo(){const lead=s.leads.find(l=>l.id===chatLeadId);if(!lead)return;s.clientTasks=clientTasks(s);if(!s.clientTasks.some(t=>t.leadId===lead.id))s.clientTasks.push({id:'client-demo-'+lead.id,leadId:lead.id,client:lead.client,title:lead.title+' · Demo',promise:'为客户制作'+lead.title+'的可交互 Demo',status:'pending',createdDay:today(s)});save();openClientTask('client-demo-'+lead.id);}

const simpleForms=new WeakMap();
function openGameSettings(){show(top('SETTINGS','游戏设置')+`<p>选择你想要的经营方式。切换模式保留当前公司和进度。</p><button class="choice ${gameMode==='simple'?'mode-selected':''}" data-game-mode="simple">简单 ${gameMode==='simple'?'✓':''}<small>LLM 为每次输入生成三个选项。选好后确认发送或执行。</small></button><button class="choice ${gameMode==='simulation'?'mode-selected':''}" data-game-mode="simulation">仿真 ${gameMode==='simulation'?'✓':''}<small>自己输入聊天、方案、文章和约定，保留现有玩法。</small></button><p class="meta">简单模式也使用已配置的 DeepSeek。生成选项不扣游戏时间或资金，但会使用 API 额度；选择不等于执行，仍需点击确认按钮。</p><p class="meta">${location.protocol==='file:'?'LLM 功能需在本地服务版使用：<a href="http://127.0.0.1:4173/">打开本地游戏</a>':'密钥和模型在 <a href="/admin.html" target="_blank">LLM 后台</a> 配置。'}</p>`)}
function updateModeLabel(){const button=document.querySelector('#game-settings');if(button)button.title='游戏设置 · '+(gameMode==='simple'?'简单':'仿真');}
function installSimpleChoices(){if(gameMode!=='simple')return;for(const form of document.querySelectorAll('#modal form')){if(!['chat-form','product-plan-form','client-demo-form','marketing-form','appointment-form','setup'].includes(form.id)||simpleForms.has(form))continue;const inputs=[...form.querySelectorAll('textarea,input')].filter(e=>!e.hasAttribute('data-setting')&&!['radio','checkbox','submit','button','hidden','password'].includes(e.type));if(!inputs.length)continue;const mount=document.createElement('section');mount.className='simple-choices';(form.id==='setup'?form.querySelector('#identity-step'):form).prepend(mount);for(const input of inputs){input.hidden=true;input.dataset.simpleHidden='1';const label=input.closest('label')||form.querySelector(`label[for="${input.id}"]`);if(label)label.hidden=true;}const state={inputs,selected:false,mount,submit:[...form.querySelectorAll('button[type="submit"]')],choices:[]};simpleForms.set(form,state);generateSimpleChoices(form);}}
async function generateSimpleChoices(form){const state=simpleForms.get(form);if(!state||!form.isConnected)return;const requestId=state.requestId=(state.requestId||0)+1;state.selected=false;state.submit.forEach(b=>b.disabled=true);state.mount.innerHTML='<div class="simple-loading" role="status">正在思考</div>';const lead=s.leads.find(l=>l.id===chatLeadId),task=clientTasks(s).find(t=>t.id===form.dataset.task);const attached=projectLibrary(s).find(p=>p.id===form.querySelector('#chat-project')?.value);const context={attachment:attached?projectMessage(attached):null,week:s.week,day:s.day||1,company:s.name,background:s.background,skills:s.skills,product:s.productPlan,client:form.id==='chat-form'||form.id==='appointment-form'?lead?{name:lead.client,need:lead.title,acquaintance:lead.acquaintance||'',history:(lead.conversation||[]).slice(-6).map(m=>({role:m.role,content:m.content.slice(0,600)}))}:null:null,task:task?{client:task.client,title:task.title,promise:task.promise,history:([...s.leads,...s.projects].find(l=>l.id===task.leadId)?.conversation||[]).slice(-4).map(m=>({role:m.role,content:m.content.slice(0,600)}))}:null,current:Object.fromEntries(state.inputs.map(el=>[el.id||el.name,String(el.value).slice(0,600)]))};try{if(location.protocol==='file:')throw Error('简单模式需要本地服务，请使用 http://127.0.0.1:4173/ 打开游戏。');const response=await fetch('/api/game-choices',{method:'POST',headers:{'Content-Type':'application/json','X-Solo-Local':'1'},body:JSON.stringify({kind:form.id,context}),signal:AbortSignal.timeout(100000)});const result=await response.json();if(!response.ok)throw Error(result.error||'生成失败');if(!form.isConnected||gameMode!=='simple'||requestId!==state.requestId)return;if(!Array.isArray(result.choices)||result.choices.length!==3)throw Error('未生成三个有效选项，请重试');state.choices=result.choices;state.mount.innerHTML='<div class="simple-mode-title">简单模式 · 三选一</div>'+result.choices.map((c,i)=>`<button type="button" class="simple-option" data-simple-option="${i}" aria-pressed="false"><span>${'ABC'[i]}</span><div><strong>${esc(c.label)}</strong><p>${esc(c.summary)}</p><details><summary>查看完整内容</summary>${Object.entries(c.values).map(([k,v])=>`<p><b>${esc(simpleFieldName(k))}：</b>${esc(v)}</p>`).join('')}</details></div></button>`).join('')+'<button type="button" class="text-btn" data-simple-retry>换三个选项</button><p class="meta">选择后，点击下方原操作按钮确认。不会自动扣费或发送。</p>'; }catch(error){if(!form.isConnected||requestId!==state.requestId)return;state.mount.innerHTML=`<p class="negative" role="alert">${esc(error.name==='TimeoutError'?'生成超时，请重试。':error.message)}</p><button type="button" class="secondary" data-simple-retry>重新生成</button><button type="button" class="text-btn" data-game-mode="simulation">切回仿真模式</button>${location.protocol==='file:'?'<p><a href="http://127.0.0.1:4173/">打开本地服务版</a></p>':''}`;}}
function simpleFieldName(k){return ({'customer-message':'发送内容','product-direction':'方向','product-audience':'目标用户','product-scenario':'场景','product-solution':'解决方式','product-price':'售价（元）','client-demo-brief':'演示方案','post-title':'文章标题','post-content':'文章正文','appointment-title':'约定事项','appointment-client':'客户',week:'第几周',day:'周内第几天','appointment-penalty':'违约赔付（元）',name:'公司名称'})[k]||k;}
document.addEventListener('submit',e=>{const state=simpleForms.get(e.target);if(gameMode==='simple'&&state&&!state.selected){e.preventDefault();e.stopImmediatePropagation();toast('请先选择一个 LLM 生成的选项');}},true);

// Native validation runs before submit; surface errors for inputs hidden by simple mode.
document.addEventListener('invalid',e=>{if(!e.target.closest('#modal'))return;e.preventDefault();const field=e.target,form=field.closest('form');let notice=form.querySelector('[data-validation-error]');if(!notice){notice=document.createElement('p');notice.dataset.validationError='1';notice.className='negative';notice.setAttribute('role','alert');form.append(notice);}notice.textContent=field.id==='previous-salary'?'原月薪请设为 3,000–50,000 元的整数。':['create-user-form','rename-user-form','register-user-form'].includes(form.id)?'故事的主角还没有名字。写下 1–24 个字，或选一个喜欢的名字。':gameMode==='simple'?'所选方案的'+simpleFieldName(field.id||field.name)+'不符合要求，请换一个选项或重新生成。':(field.validationMessage||'请检查填写内容');},true);

async function publishMarketing(form){
 if(chatBusy)return;
 const error=form.querySelector('#marketing-error'),button=form.querySelector('button[type="submit"]');
 error.textContent='';
 if(s.ended||s.pendingEvent||dayUsed(s)>=2){error.textContent=dayUsed(s)>=2?'今天的两个时段已用完，请先返回工作室结束今天，明天再发布。':'请先处理当前经营结果';return;}
 const content=form.querySelector('#post-title').value+'\n'+form.querySelector('#post-content').value;
 const label=button.textContent;chatBusy=true;button.disabled=true;button.textContent='正在思考';
 try{
  if(location.protocol==='file:')throw Error('文章反馈需要本地服务，请使用 http://127.0.0.1:4173/ 打开游戏。');
  const response=await fetch('/api/marketing-evaluate',{method:'POST',headers:{'Content-Type':'application/json','X-Solo-Local':'1'},body:JSON.stringify({content,context:{product:s.productPlan,background:s.background,skills:s.skills}}),signal:AbortSignal.timeout(100000)});
  const result=await response.json();if(!response.ok)throw Error(result.error||'文章反馈生成失败');
  chatBusy=false;executeBranch('market',undefined,content,result);
 }catch(err){chatBusy=false;if(form.isConnected){error.textContent=(err.name==='TimeoutError'?'反馈生成超时，请重试。':err.message)+' 本次未消耗游戏时间和资金，文章已保留。';button.disabled=false;button.textContent=label;}}
}

function integrateDeskHUD(){
 const stats=document.querySelector('#stats');
 if(view!=='overview'){document.querySelector('main header').after(stats);return;}
 const scene=document.querySelector('.workstation-scene');if(!scene)return;
 const hud=document.createElement('div');hud.className='desk-hud';hud.setAttribute('aria-label','工作位经营状态');
 scene.prepend(hud);hud.append(stats);
 const skills=document.querySelector('.skills-panel');if(skills)hud.append(skills);
 const founder=document.querySelector('.founder-summary');if(founder)scene.append(founder);const quest=document.createElement('button');quest.type='button';quest.className='desk-quest';quest.dataset.journey='';const q=journeyStatus(s);quest.innerHTML='<small>创业之路 · '+q.done+'/5</small><strong>'+(q.next?MILESTONES[q.next-1].title:'五枚勋章，属于你')+'</strong><span>'+journeyProgress(q)+'</span>';scene.append(quest);
}

function openSCRM(filter='all'){
 const stages=[['all','全部'],['new','新线索'],['followup','跟进中'],['converted','待签约'],['project','合作中'],['rejected','暂不合作']];
 const entries=[...s.leads.map(l=>({...l,crmStage:l.status||'new'})),...s.projects.map(p=>({...p,crmStage:'project'}))];
 const visible=entries.filter(l=>filter==='all'||l.crmStage===filter);
 show(top('SCRM · CUSTOMER WORKSPACE','客户管理')+`<p>线索、沟通和合作进度集中在这里。查看不消耗时间，点击客户即可继续跟进。</p><div class="scrm-summary"><span>客户记录 <b>${entries.length}</b></span><span>待跟进 <b>${entries.filter(l=>['new','followup'].includes(l.crmStage)).length}</b></span><span>待签约 <b>${entries.filter(l=>l.crmStage==='converted').length}</b></span><span>合作中 <b>${s.projects.length}</b></span></div><div class="scrm-filters" aria-label="客户阶段">${stages.map(([id,name])=>`<button type="button" class="${id===filter?'selected':''}" data-scrm-filter="${id}" aria-pressed="${id===filter}">${name} <small>${id==='all'?entries.length:entries.filter(l=>l.crmStage===id).length}</small></button>`).join('')}</div><div class="scrm-list">${visible.map(l=>{
 const profile=contactProfile(l),last=(l.conversation||[]).filter(m=>m.role==='assistant').at(-1),tasks=clientTasks(s).filter(t=>t.leadId===l.id),stage=stages.find(([id])=>id===l.crmStage)?.[1]||'待跟进';
 return `<article class="scrm-card"><div class="scrm-card-heading"><div><h3>${esc(l.client)}</h3><span class="meta">${esc(profile.name)} · ${esc(profile.role)} · ${esc(profile.industry)}</span></div><span class="pill">${stage}</span></div><p><strong>${esc(l.title)}</strong> · ${fmt(l.price)} · ${l.hours} 小时工作量</p><p class="meta">来源：${esc(l.source||'主动拓客')}${l.acquaintance?' · '+esc(l.acquaintance):''}${l.relationship?.stage?' · 关系：'+esc(l.relationship.stage):''}</p>${last?`<div class="scrm-feedback">最近反馈：${esc(last.content.slice(0,160))}${last.content.length>160?'…':''}</div>`:'<div class="scrm-feedback">尚无沟通记录，先了解需求再开始对话。</div>'}${tasks.map(t=>`<button class="text-btn" data-client-task="${esc(t.id)}">Demo 承诺：${t.status==='pending'?'待开发':t.status==='sent'?'已发送':'已完成，待发送'} →</button>`).join('')}<div class="scrm-card-footer"><span class="meta">${l.crmStage==='project'?'已交付进度 '+Math.round(l.progress/l.hours*100)+'% · 第 '+l.due+' 周到期':l.crmStage==='converted'?'客户已有合作意愿，签约后开始交付':l.crmStage==='rejected'?'本轮沟通已结束':'继续在微信中了解需求'}</span>${l.crmStage==='project'?'<button class="primary" data-branch="delivery">打开 Agent 交付</button>':`<button class="primary" data-accept="${l.id}">${l.crmStage==='converted'?'查看合作 / 签约':l.crmStage==='rejected'?'查看沟通记录':'去微信跟进'}</button>`}</div></article>`;
 }).join('')||'<div class="empty">这个阶段暂无客户。打开微信寻找客户，或发布公众号文章获取咨询。</div>'}</div><div class="modal-actions"><button class="secondary" data-workspace="wechat">打开微信</button><button class="secondary" data-workspace="article">写公众号获客</button></div>`);
 modal.classList.add('chat-modal','scrm-modal');
}

function deskSchedule(){
 const day=today(s),actions=(s.dayHistory||[]).filter(a=>a.day===day),due=agenda(s).filter(a=>['pending','overdue'].includes(a.status)).sort((a,b)=>a.due-b.due);
 const next=due[0];
 return `<aside class="desk-schedule" aria-label="今日日程"><div class="desk-schedule-head" tabindex="0" aria-label="拖动日程表；方向键移动，双击或 Home 键复位" title="拖动换位置 · 双击复位"><strong>⠿ 今日日程</strong><button type="button" data-open-calendar aria-label="打开完整日程">↗</button></div><div class="desk-schedule-date">第 ${s.week} 周 · 第 ${s.day||1} 天</div><div class="desk-week-strip" aria-label="本周进度">${Array.from({length:7},(_,i)=>`<span class="${i+1===(s.day||1)?'current':''}">${i+1}</span>`).join('')}</div><div class="desk-time-slots">${[0,1].map(i=>`<div class="desk-time-slot ${actions[i]?'done':''}"><small>时段 ${i+1}</small><span>${actions[i]?esc(actions[i].title):i<dayUsed(s)?'已使用':'空闲 · 可安排工作'}</span></div>`).join('')}</div><button class="desk-due ${next&&next.due<=day?'urgent':''}" type="button" data-open-calendar>${next?`<small>${next.due<day?'已逾期':next.due===day?'今天到期':'最近待办'}</small><strong>${esc(next.title)}</strong><span>${esc(next.client||'个人约定')} · 第 ${Math.ceil(next.due/7)} 周第 ${(next.due-1)%7+1} 天</span><span>共 ${due.length} 项待办 · 查看全部 ›</span>`:'<small>近期约定</small><span>暂无待办 · 打开日程登记 ›</span>'}</button><button class="desk-schedule-end" type="button" data-do="advance">${s.ended?'查看结局':s.pendingEvent?'处理经营事件':s.day===7?'结束今天 · 本周结算':'结束今天 →'}</button></aside>`;
}

